import { DROPS } from "./drops";

// The OGCW Shop ("Brand deals"): brands and products, every one bought
// straight from the shop that sells it ("Shop at …" links out; OGCW takes no
// payments and keeps no stock). The cart is a list to buy from: checkout
// sends each piece to its shop (src/components/shop-cart.tsx). Prices are
// guide retail prices in euros; where we couldn't confirm one, the product
// shows "Price at the shop" instead. Every product photo is the product
// alone on the same black stage: free-licence photos (Wikimedia Commons,
// Unsplash) with the background removed, credited on each product page.
// Streaming subscriptions show the service's logo.

export type ShopCategory = "Sneakers" | "Clothing" | "Accessories" | "Streaming";
export const SHOP_CATEGORIES: { id: ShopCategory; slug: string; label: string; blurb: string }[] = [
  { id: "Sneakers", slug: "sneakers", label: "Sneakers", blurb: "Jordans, terrace classics, runners and the pairs on the release calendar." },
  { id: "Clothing", slug: "clothing", label: "Clothing", blurb: "Football shirts, basketball jerseys, merch and limited editions." },
  { id: "Accessories", slug: "accessories", label: "Watches & chains", blurb: "Rolex to Casio, gold chains, caps and shades." },
  { id: "Streaming", slug: "streaming", label: "Streaming", blurb: "The subscriptions for films, music, sport and games." },
];
export const categoryOf = (slug: string) => SHOP_CATEGORIES.find((category) => category.slug === slug);

export type ShopBrand = { slug: string; name: string; blurb: string; site: string; search?: (q: string) => string; /** A shop that sells many brands (resale, vintage) */ store?: boolean };
const q = (base: string) => (query: string) => base + encodeURIComponent(query);

