export type ShopTag = "new" | "trending" | "gift" | "drops" | "limited";
export type ShopProduct = {
  id: string;
  brand: string;
  name: string;
  colour: string;
  category: ShopCategory;
  /** A finer type: Running, Watches, Football shirts, Music… */
  kind: string;
  /** Guide retail price in euros; none when we couldn't confirm it */
  price?: number;
  image: string;
  credit: string;
  photoPage?: string;
  tags?: ShopTag[];
  /** The OGCW story it belongs to */
  story?: string;
  /** Where it's bought, when not from the brand itself (resale, vintage, jewellers) */
  retailer?: string;
  /** The shop's own page for it */
  url?: string;
};

