export const getProduct = (id: string) => PRODUCTS.find((product) => product.id === id);
export const brandOf = (product: ShopProduct) => getBrand(product.brand)!;
/** The shop it's bought from: the brand itself, or a resale / vintage shop */
export const retailerOf = (product: ShopProduct) => getBrand(product.retailer ?? product.brand) ?? brandOf(product);
/** Where "Shop at …" goes: the shop's own page, or its search for the product */
export const buyUrl = (product: ShopProduct) => {
  if (product.url) return product.url;
  const shop = retailerOf(product);
  const brand = brandOf(product);
  const words = shop.slug === brand.slug || brand.store ? `${product.name} ${product.colour.split(",")[0]}` : `${brand.name} ${product.name}`;
  return shop.search ? shop.search(words) : shop.site;
};
/** A product's full name: brand and name, without saying the brand twice */
export const fullName = (product: ShopProduct) => {
  const brand = brandOf(product);
  return brand.store || product.name.toLowerCase().includes(brand.name.toLowerCase()) ? product.name : `${brand.name} ${product.name}`;
};
export const productsOf = (brand: string) => PRODUCTS.filter((product) => product.brand === brand || product.retailer === brand);
export const productsIn = (category: ShopCategory) => PRODUCTS.filter((product) => product.category === category);
export const SNEAKER_DROPS = DROPS.filter((drop) => drop.kind === "Sneakers");

// The gift guide: price bands
export const GIFT_BANDS = [
  { id: "under-50", label: "Under €50", test: (price?: number) => price !== undefined && price < 50 },
  { id: "under-100", label: "Under €100", test: (price?: number) => price !== undefined && price >= 50 && price < 100 },
  { id: "under-200", label: "Under €200", test: (price?: number) => price !== undefined && price >= 100 && price < 200 },
  { id: "big", label: "The big gift", test: (price?: number) => price !== undefined && price >= 200 },
] as const;
